"""The ``stockroom`` command line."""

import csv
import io
import json
import os
import sys

from .catalog import parse_catalog
from .errors import ParseError
from .fulfilment import plan_fulfil, shipped_so_far, status_of_order
from .movements import Movement, parse_date, parse_movements, QTY_RE
from .orders import Order, normalise_order_id, parse_orders
from .pricing import ZERO, price_order
from .shelves import breaks_rule, buy_quantity, history, status_of, stock_levels
from .catalog import normalise_sku, UINT_RE
from .textfile import decode, to_int

CATALOG, MOVEMENTS, ORDERS = "catalog.txt", "movements.txt", "orders.txt"

USAGE = """\
usage: stockroom [--dir DIR] COMMAND [ARGS]
  stock [--json]
  low [--json]
  history SKU [--json]
  receive DATE SKU QUANTITY [NOTE]
  ship DATE SKU QUANTITY [NOTE]
  quote ORDER [--json]
  fulfil ORDER DATE
  invoice ORDER [--json]
  report [--format text|csv|json]
"""

# command -> (files read, min args, max args, options allowed)
COMMANDS = {
    "stock": ((CATALOG, MOVEMENTS), 0, 0, ("--json",)),
    "low": ((CATALOG, MOVEMENTS), 0, 0, ("--json",)),
    "history": ((CATALOG, MOVEMENTS), 1, 1, ("--json",)),
    "receive": ((CATALOG, MOVEMENTS), 3, 4, ()),
    "ship": ((CATALOG, MOVEMENTS), 3, 4, ()),
    "quote": ((CATALOG, ORDERS), 1, 1, ("--json",)),
    "fulfil": ((CATALOG, MOVEMENTS, ORDERS), 2, 2, ()),
    "invoice": ((CATALOG, MOVEMENTS, ORDERS), 1, 1, ("--json",)),
    "report": ((CATALOG, MOVEMENTS, ORDERS), 0, 0, ("--format",)),
}


class Failure(Exception):
    """Stop with ``code`` (1 refusal/data mistake, 2 usage/unreadable) and a message."""

    def __init__(self, code, message):
        super().__init__(message)
        self.code = code
        self.message = message


def usage_error(message):
    return Failure(2, "%s\n%s" % (message, USAGE.rstrip("\n")))


# ---------------------------------------------------------------- command line

def parse_command_line(argv):
    """Return ``(command, directory, flags, args)`` or raise Failure(2)."""
    rest = []
    directory = None
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir" or arg.startswith("--dir="):
            if directory is not None:
                raise usage_error("--dir given more than once")
            if arg == "--dir":
                i += 1
                if i >= len(argv):
                    raise usage_error("--dir needs a value")
                directory = argv[i]
            else:
                directory = arg[len("--dir="):]
        else:
            rest.append(arg)
        i += 1
    if not rest:
        raise usage_error("no command given")
    command, rest = rest[0], rest[1:]
    if command not in COMMANDS:
        raise usage_error("unknown command %r" % command)
    _, low, high, options = COMMANDS[command]
    flags = {}
    args = []
    i = 0
    while i < len(rest):
        arg = rest[i]
        if options and arg.startswith("-"):
            name, eq, value = arg.partition("=")
            if name not in options or name in flags or (name == "--json" and eq):
                raise usage_error("bad option %r" % arg)
            if name == "--format":
                if not eq:
                    i += 1
                    if i >= len(rest):
                        raise usage_error("--format needs a value")
                    value = rest[i]
                if value not in ("text", "csv", "json"):
                    raise usage_error("bad --format value %r (want text, csv or json)" % value)
                flags[name] = value
            else:
                flags[name] = True
        elif not options or not arg.startswith("-") or command in ("receive", "ship", "fulfil"):
            args.append(arg)
        i += 1
    if not low <= len(args) <= high:
        raise usage_error("wrong number of arguments for %s" % command)
    if command in ("receive", "ship", "fulfil"):
        date_text = args[1] if command == "fulfil" else args[0]
        if parse_date(date_text) is None:
            raise usage_error("bad date %r (want a real YYYY-MM-DD date)" % date_text)
    if directory is None:
        directory = "."
    return command, directory, flags, args


# ------------------------------------------------------------------- reading

def read_files(directory, names):
    """Return dict name -> bytes. Missing movements/orders are empty; the rest exit 2."""
    if not os.path.isdir(directory):
        raise Failure(2, "stockroom: %s: not a folder" % directory)
    raw = {}
    for name in names:
        path = os.path.join(directory, name)
        try:
            with open(path, "rb") as handle:
                raw[name] = handle.read()
        except FileNotFoundError:
            if name == CATALOG:
                raise Failure(2, "stockroom: %s: file not found" % name)
            raw[name] = b""
        except OSError as error:
            raise Failure(2, "stockroom: %s: cannot read (%s)" % (name, error.strerror or error))
    text = {}
    for name, data in raw.items():
        try:
            text[name] = decode(data)
        except UnicodeDecodeError:
            raise Failure(2, "stockroom: %s: not valid UTF-8" % name)
    return raw, text


def parse_with_name(name, function, *args):
    try:
        return function(*args)
    except ParseError as error:
        raise Failure(1, "stockroom: %s: %s" % (name, error))


def append_lines(directory, raw_movements, lines):
    """Append ``lines`` to movements.txt without touching existing bytes."""
    prefix = b"\n" if raw_movements and not raw_movements.endswith(b"\n") else b""
    data = prefix + "".join(line + "\n" for line in lines).encode("utf-8")
    path = os.path.join(directory, MOVEMENTS)
    try:
        with open(path, "ab") as handle:
            handle.write(data)
    except OSError as error:
        raise Failure(2, "stockroom: %s: cannot write (%s)" % (MOVEMENTS, error.strerror or error))


# -------------------------------------------------------------------- output

def dump(value):
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def money(amount):
    return format(amount, "f")


def signed(quantity):
    return "%+d" % quantity


def quote_text(header, quote):
    out = [header]
    for line in quote.lines:
        out.append(
            "%s %d %s %s %s %s"
            % (line.sku, line.quantity, money(line.unit), money(line.gross), money(line.discount), money(line.net))
        )
    out.append("subtotal " + money(quote.subtotal))
    out.append("order discount " + money(quote.order_discount))
    out.append("tax " + money(quote.tax))
    out.append("total " + money(quote.total))
    return "\n".join(out) + "\n"


def quote_json(order, quote):
    return dump(
        {
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "lines": [
                {
                    "sku": line.sku,
                    "quantity": line.quantity,
                    "unit": money(line.unit),
                    "gross": money(line.gross),
                    "discount": money(line.discount),
                    "net": money(line.net),
                }
                for line in quote.lines
            ],
            "subtotal": money(quote.subtotal),
            "order_discount": money(quote.order_discount),
            "tax": money(quote.tax),
            "total": money(quote.total),
        }
    )


# ------------------------------------------------------------------ commands

def find_order(orders, text):
    wanted = normalise_order_id(text)
    for order in orders:
        if order.id == wanted:
            return order
    raise Failure(1, "stockroom: unknown order %r" % text)


def cmd_stock(flags, args, catalog, movements, **_):
    levels = stock_levels(catalog, movements)
    rows = [
        (sku, levels[sku], status_of(levels[sku], catalog[sku].reorder), catalog[sku].name)
        for sku in sorted(catalog)
    ]
    if flags.get("--json"):
        return dump([{"sku": s, "name": n, "onhand": o, "status": st} for s, o, st, n in rows])
    return "".join("%s %d %s %s\n" % row for row in rows)


def cmd_low(flags, args, catalog, movements, **_):
    levels = stock_levels(catalog, movements)
    rows = []
    for sku in sorted(catalog):
        if status_of(levels[sku], catalog[sku].reorder) != "ok":
            reorder = catalog[sku].reorder
            rows.append((sku, levels[sku], reorder, buy_quantity(levels[sku], reorder)))
    if flags.get("--json"):
        return dump([{"sku": s, "onhand": o, "reorder": r, "buy": b} for s, o, r, b in rows])
    return "".join("%s %d %d %d\n" % row for row in rows)


def cmd_history(flags, args, catalog, movements, **_):
    sku = normalise_sku(args[0])
    if sku is None or sku not in catalog:
        raise Failure(1, "stockroom: unknown SKU %r" % args[0])
    rows = history(sku, movements)
    if flags.get("--json"):
        return dump(
            [
                {"date": m.date.isoformat(), "delta": signed(m.quantity), "balance": b, "note": m.note}
                for m, b in rows
            ]
        )
    return "".join(
        "%s %s %d%s\n" % (m.date.isoformat(), signed(m.quantity), b, " " + m.note if m.note else "")
        for m, b in rows
    )


def cmd_move(direction):
    def run(flags, args, catalog, movements, directory, raw, **_):
        date_text, sku_text, qty_text = args[0], args[1], args[2]
        note = args[3].strip(" \t") if len(args) == 4 else ""
        sku = normalise_sku(sku_text)
        if sku is None or sku not in catalog:
            raise Failure(1, "stockroom: unknown SKU %r" % sku_text)
        if not UINT_RE.fullmatch(qty_text) or to_int(qty_text) in (None, 0):
            raise Failure(1, "stockroom: bad quantity %r (want a whole number of one or more, no sign)" % qty_text)
        if "\n" in note or "\r" in note:
            raise Failure(1, "stockroom: a note may not contain a line break")
        quantity = to_int(qty_text) * direction
        move = Movement(parse_date(date_text), sku, quantity, note)
        message = breaks_rule(movements, move)
        if message:
            raise Failure(1, "stockroom: %s: %s" % (MOVEMENTS, message))
        line = "%s %s %s%s" % (date_text, sku, signed(quantity), " " + note if note else "")
        try:
            line.encode("utf-8")
        except UnicodeEncodeError:
            raise Failure(1, "stockroom: the note is not valid text")
        append_lines(directory, raw[MOVEMENTS], [line])
        return line + "\n"

    return run


def cmd_quote(flags, args, catalog, orders, **_):
    order = find_order(orders, args[0])
    quote = price_order(order, catalog)
    if flags.get("--json"):
        return quote_json(order, quote)
    return quote_text("%s %s %s" % (order.id, order.date.isoformat(), order.customer), quote)


def cmd_fulfil(flags, args, catalog, movements, orders, directory, raw, **_):
    order = find_order(orders, args[0])
    date = parse_date(args[1])
    if date < order.date:
        raise Failure(1, "stockroom: %s: DATE %s is before the order date %s" % (order.id, args[1], order.date.isoformat()))
    plans = plan_fulfil(order, movements, date)
    new_lines = ["%s %s -%d order %s" % (args[1], p.sku, p.ship, order.id) for p in plans if p.ship > 0]
    if new_lines:
        append_lines(directory, raw[MOVEMENTS], new_lines)
    shipped = {p.sku: p.shipped_after for p in plans}
    out = ["%s shipped %d backordered %d" % (p.sku, p.ship, p.backordered) for p in plans]
    out.append("status " + status_of_order(order, shipped))
    return "\n".join(out) + "\n"


def shipped_order(order, movements):
    """The order restricted to what has shipped, and the shipped dict."""
    shipped = shipped_so_far(order, movements)
    lines = [(sku, shipped[sku]) for sku, _ in order.lines if shipped[sku] > 0]
    return Order(order.id, order.date, order.customer, lines), shipped


def cmd_invoice(flags, args, catalog, movements, orders, **_):
    order = find_order(orders, args[0])
    sent, _ = shipped_order(order, movements)
    if not sent.lines:
        raise Failure(1, "stockroom: %s: nothing has shipped yet" % order.id)
    quote = price_order(sent, catalog)
    if flags.get("--json"):
        return quote_json(sent, quote)
    return quote_text("invoice %s %s %s" % (order.id, order.date.isoformat(), order.customer), quote)


def cmd_report(flags, args, catalog, movements, orders, **_):
    rows = []
    for order in sorted(orders, key=lambda o: (o.date, int(o.id[3:]), o.id)):
        sent, shipped = shipped_order(order, movements)
        invoiced = price_order(sent, catalog).total if sent.lines else ZERO
        rows.append(
            {
                "order": order.id,
                "date": order.date.isoformat(),
                "customer": order.customer,
                "status": status_of_order(order, shipped),
                "ordered": sum(q for _, q in order.lines),
                "shipped": sum(q for _, q in sent.lines),
                "quoted": money(price_order(order, catalog).total),
                "invoiced": money(invoiced),
            }
        )
    fmt = flags.get("--format", "text")
    if fmt == "json":
        return dump(rows)
    if fmt == "csv":
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        writer.writerow(["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"])
        for r in rows:
            writer.writerow([r["order"], r["date"], r["customer"], r["status"], r["ordered"], r["shipped"], r["quoted"], r["invoiced"]])
        return buffer.getvalue()
    return "".join(
        "%s %s %s %s %d/%d %s %s\n"
        % (r["order"], r["date"], r["customer"], r["status"], r["shipped"], r["ordered"], r["quoted"], r["invoiced"])
        for r in rows
    )


HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": cmd_move(+1),
    "ship": cmd_move(-1),
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}


def execute(argv):
    """Run a command line; return the text for stdout. Raises Failure."""
    command, directory, flags, args = parse_command_line(argv)
    names = COMMANDS[command][0]
    raw, text = read_files(directory, names)
    catalog = parse_with_name(CATALOG, parse_catalog, text[CATALOG])
    movements = orders = None
    if MOVEMENTS in names:
        movements = parse_with_name(MOVEMENTS, parse_movements, text[MOVEMENTS], catalog)
    if ORDERS in names:
        orders = parse_with_name(ORDERS, parse_orders, text[ORDERS], catalog)
    return HANDLERS[command](
        flags, args, catalog=catalog, movements=movements, orders=orders, directory=directory, raw=raw
    )


# ---------------------------------------------------------------------- main

def _write(stream, text):
    data = text.encode("utf-8", "replace")
    buffer = getattr(stream, "buffer", None)
    if buffer is not None:
        buffer.write(data)
        buffer.flush()
    else:
        stream.write(data.decode("utf-8"))
        stream.flush()


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    try:
        output = execute(list(argv))
    except Failure as failure:
        _write(sys.stderr, failure.message + "\n")
        return failure.code
    try:
        if output:
            _write(sys.stdout, output)
    except BrokenPipeError:
        _silence_stdout()
        return 0
    except (OSError, AttributeError, ValueError) as error:
        # Closed stdout (None), full disk, or a stream already closed.
        _silence_stdout()
        reason = getattr(error, "strerror", None) or str(error)
        if sys.stdout is None or isinstance(error, AttributeError):
            reason = "standard output is closed"
        _write(sys.stderr, "stockroom: cannot write output: %s\n" % reason)
        return 2
    return 0


def _silence_stdout():
    """Point fd 1 at the null device so the exit-time flush cannot fail again."""
    try:
        os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass
