CATALOG, MOVEMENTS, ORDERS = "catalog.txt", "movements.txt", "orders.txt"

USAGE = """\
usage: stockroom [--dir DIR] COMMAND [ARGS]
  stock [--json]
  low [--json]
  history SKU [--json]
  receive DATE SKU QUANTITY [NOTE]
  ship DATE SKU QUANTITY [NOTE]
  quote ORDER [--json]
  fulfil ORDER DATE
  invoice ORDER [--json]
  report [--format text|csv|json]
