# command -> (files read, min args, max args, options allowed)
COMMANDS = {
    "stock": ((CATALOG, MOVEMENTS), 0, 0, ("--json",)),
    "low": ((CATALOG, MOVEMENTS), 0, 0, ("--json",)),
    "history": ((CATALOG, MOVEMENTS), 1, 1, ("--json",)),
    "receive": ((CATALOG, MOVEMENTS), 3, 4, ()),
    "ship": ((CATALOG, MOVEMENTS), 3, 4, ()),
    "quote": ((CATALOG, ORDERS), 1, 1, ("--json",)),
    "fulfil": ((CATALOG, MOVEMENTS, ORDERS), 2, 2, ()),
    "invoice": ((CATALOG, MOVEMENTS, ORDERS), 1, 1, ("--json",)),
    "report": ((CATALOG, MOVEMENTS, ORDERS), 0, 0, ("--format",)),
}


class Failure(Exception):
    """Stop with ``code`` (1 refusal/data mistake, 2 usage/unreadable) and a message."""

    def __init__(self, code, message):
        super().__init__(message)
        self.code = code
        self.message = message


def usage_error(message):
    return Failure(2, "%s\n%s" % (message, USAGE.rstrip("\n")))


# ---------------------------------------------------------------- command line

def parse_command_line(argv):
    """Return ``(command, directory, flags, args)`` or raise Failure(2)."""
    rest = []
    directory = None
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir" or arg.startswith("--dir="):
            if directory is not None:
                raise usage_error("--dir given more than once")
            if arg == "--dir":
                i += 1
                if i >= len(argv):
                    raise usage_error("--dir needs a value")
                directory = argv[i]
            else:
                directory = arg[len("--dir="):]
        else:
            rest.append(arg)
        i += 1
    if not rest:
        raise usage_error("no command given")
    command, rest = rest[0], rest[1:]
    if command not in COMMANDS:
        raise usage_error("unknown command %r" % command)
    _, low, high, options = COMMANDS[command]
    flags = {}
    args = []
    i = 0
    while i < len(rest):
        arg = rest[i]
        if options and arg.startswith("-"):
            name, eq, value = arg.partition("=")
            if name not in options or name in flags or (name == "--json" and eq):
                raise usage_error("bad option %r" % arg)
            if name == "--format":
                if not eq:
                    i += 1
                    if i >= len(rest):
                        raise usage_error("--format needs a value")
                    value = rest[i]
                if value not in ("text", "csv", "json"):
                    raise usage_error("bad --format value %r (want text, csv or json)" % value)
                flags[name] = value
            else:
                flags[name] = True
        elif not options or not arg.startswith("-") or command in ("receive", "ship", "fulfil"):
            args.append(arg)
        i += 1
    if not low <= len(args) <= high:
        raise usage_error("wrong number of arguments for %s" % command)
    if command in ("receive", "ship", "fulfil"):
        date_text = args[1] if command == "fulfil" else args[0]
        if parse_date(date_text) is None:
            raise usage_error("bad date %r (want a real YYYY-MM-DD date)" % date_text)
